('school-jnvst-6', 'school-admission', 'Central', 'Navodaya', 'Jawahar Navodaya Vidyalaya admission, Class 6 (JNVST)', 'Navodaya Vidyalaya Samiti', 'Free residential, co-educational schools run by the Government of India, one in most districts. Children studying Class 5 apply through the Jawahar Navodaya Vidyalaya Selection Test for the Navodaya in their own district. Most seats are kept for children from rural areas.', '{"studyingAt":["class5"],"manualChecks":["Studying Class 5 in a government or government-recognised school in the same district as the Navodaya","Date of birth falls inside the window given in this year''s notice","Rural-quota seats need the child to have studied Classes 3, 4 and 5 in rural areas"]}'::jsonb, '{"amount":"Education, boarding and lodging are free","selection":"Selection test (mental ability, arithmetic, language)","documents":["Photo and signature of the child and parent","Certificate from the head of the current school","Aadhaar or residence proof"],"entryClass":"Class 6","tags":["residential","free","rural"]}'::jsonb, null, 'https://navodaya.gov.in', 'Navodaya Vidyalaya Samiti', null, 'in-review', true),
('school-jnvst-9', 'school-admission', 'Central', 'Navodaya', 'Jawahar Navodaya Vidyalaya lateral entry, Class 9', 'Navodaya Vidyalaya Samiti', 'A selection test for the few seats that fall vacant in Class 9 at each Navodaya. For children studying Class 8 in the same district.', '{"studyingAt":["class8"],"manualChecks":["Studying Class 8 in a government or recognised school in the same district","Date of birth falls inside the window given in this year''s notice"]}'::jsonb, '{"selection":"Selection test (English, Hindi, Maths, Science)","entryClass":"Class 9","tags":["residential","lateral entry"]}'::jsonb, null, 'https://navodaya.gov.in', 'Navodaya Vidyalaya Samiti', null, 'in-review', true),
('school-aissee-6', 'school-admission', 'Central', 'Sainik', 'Sainik School admission, Class 6 (AISSEE)', 'Sainik Schools Society, exam by National Testing Agency', 'Residential schools that prepare children for the National Defence Academy and other officer entries. Admission to Class 6 is through the All India Sainik Schools Entrance Examination. Girls can apply for Class 6.', '{"studyingAt":["class5"],"manualChecks":["Age limit for Class 6 as given in this year''s notice (usually around 10 to 12 years)","Seat reservation for the home state, SC, ST, OBC and defence wards"]}'::jsonb, '{"amount":"Fees apply; state and central scholarships are available for many students","selection":"Written exam (maths, intelligence, language, general knowledge), then medical check","documents":["Birth certificate","Domicile certificate","Category certificate if any"],"entryClass":"Class 6","tags":["defence","residential"]}'::jsonb, null, 'https://exams.nta.ac.in/AISSEE/', 'NTA, AISSEE page', null, 'in-review', true),
('school-aissee-9', 'school-admission', 'Central', 'Sainik', 'Sainik School admission, Class 9 (AISSEE)', 'Sainik Schools Society, exam by National Testing Agency', 'Class 9 entry to Sainik Schools through the same entrance exam. For children studying Class 8 in a recognised school.', '{"studyingAt":["class8"],"manualChecks":["Age limit for Class 9 as given in this year''s notice (usually around 13 to 15 years)","Whether girls can apply for Class 9 at the school you choose"]}'::jsonb, '{"selection":"Written exam (maths, intelligence, English, general science, social studies), then medical check","entryClass":"Class 9","tags":["defence","residential"]}'::jsonb, null, 'https://exams.nta.ac.in/AISSEE/', 'NTA, AISSEE page', null, 'in-review', true),
('school-rms-cet', 'school-admission', 'Central', 'Military School', 'Rashtriya Military School admission (CET), Class 6 and Class 9', 'Rashtriya Military Schools, Ministry of Defence', 'Five residential schools at Ajmer, Bengaluru, Belagavi, Chail and Dholpur. A Common Entrance Test is held for Class 6 and Class 9. Seats are kept for children of defence personnel, with some open to civilians.', '{"studyingAt":["class5","class8"],"manualChecks":["Age limit for the class you apply to, as given in this year''s notice","Seat quota for wards of serving or retired defence personnel and for civilians","Whether girls are admitted this year"]}'::jsonb, '{"selection":"Common Entrance Test, interview and medical check","entryClass":"Class 6 and Class 9","tags":["defence","residential"]}'::jsonb, null, 'https://www.rashtriyamilitaryschools.edu.in', 'Rashtriya Military Schools', null, 'in-review', true),
('school-kv-class1', 'school-admission', 'Central', 'Kendriya Vidyalaya', 'Kendriya Vidyalaya admission, Balvatika and Class 1', 'Kendriya Vidyalaya Sangathan', 'Central government schools across India with CBSE curriculum. Balvatika and Class 1 admissions are online, by lottery within priority categories. Children of central government employees, including transferable staff, get the highest priority.', '{"manualChecks":["Child''s age on the cut-off date in this year''s admission guidelines (Class 1 needs at least 6 years)","Your priority category (central government employee, state government, PSU, others)"]}'::jsonb, '{"amount":"Low fees; some groups are exempt","selection":"Online registration, then lottery within priority categories","documents":["Birth certificate","Residence proof","Service certificate of the parent, if claiming priority","Category certificate if any"],"entryClass":"Balvatika and Class 1","tags":["CBSE","central government"]}'::jsonb, null, 'https://kvsangathan.nic.in', 'Kendriya Vidyalaya Sangathan', null, 'in-review', true),
('school-kv-other', 'school-admission', 'Central', 'Kendriya Vidyalaya', 'Kendriya Vidyalaya admission, Class 2 onwards and Class 11', 'Kendriya Vidyalaya Sangathan', 'Admission to Class 2 and above is offline at each school, only where seats are vacant. Class 11 admission depends on Class 10 marks and the streams the school offers.', '{"manualChecks":["Vacant seats in the class at the school you want","Age on the cut-off date for that class","For Class 11: marks needed for the stream you want"]}'::jsonb, '{"selection":"Registration at the school; for Class 11, merit in Class 10","entryClass":"Class 2 to Class 11","tags":["CBSE","central government"]}'::jsonb, null, 'https://kvsangathan.nic.in', 'Kendriya Vidyalaya Sangathan', null, 'in-review', true),
('school-emrs-6', 'school-admission', 'Central', 'EMRS', 'Eklavya Model Residential School admission, Class 6', 'National Education Society for Tribal Students, Ministry of Tribal Affairs', 'Free residential schools for Scheduled Tribe children, in many states including Telangana and Andhra Pradesh. Class 6 admission is through an entrance test conducted by the state.', '{"studyingAt":["class5"],"categories":["ST"],"manualChecks":["Age and residence conditions in your state''s notice","Some seats may be open to non-ST children"]}'::jsonb, '{"amount":"Education, boarding and lodging are free","selection":"Entrance test conducted by the state society","entryClass":"Class 6","tags":["residential","free","tribal"]}'::jsonb, null, 'https://nests.tribal.gov.in', 'NESTS, Ministry of Tribal Affairs', null, 'in-review', true),
('school-tg-gurukul-5', 'school-admission', 'State', 'State residential', 'Telangana Gurukul schools admission, Class 5 (TGCET)', 'Telangana social, tribal, BC and general welfare residential societies', 'One common entrance test for admission to Class 5 in Telangana''s residential welfare schools (Gurukulams). Education, food and hostel are free.', '{"states":["Telangana"],"manualChecks":["Studying Class 4 in a government or recognised school in Telangana","Age and family income limits in this year''s notice"]}'::jsonb, '{"amount":"Education, boarding and lodging are free","selection":"Common entrance test","entryClass":"Class 5","tags":["residential","free","state"]}'::jsonb, null, 'https://tgcet.cgg.gov.in', 'TGCET portal', null, 'in-review', true),
('school-ap-residential-5', 'school-admission', 'State', 'State residential', 'Andhra Pradesh residential schools admission, Class 5', 'AP Residential Educational Institutions Society and welfare residential societies', 'Entrance tests for Class 5 admission in Andhra Pradesh residential schools, including APREIS schools and the social and tribal welfare Gurukulams.', '{"states":["Andhra Pradesh"],"manualChecks":["Studying Class 4 in a government or recognised school in Andhra Pradesh","Age and family income limits in this year''s notice"]}'::jsonb, '{"selection":"Entrance test","entryClass":"Class 5","tags":["residential","state"]}'::jsonb, null, 'https://aprs.apcfss.in', 'APREIS admissions portal', null, 'in-review', true),
('school-nmms', 'scholarship', 'Central', 'School scholarship', 'National Means-cum-Merit Scholarship (NMMS)', 'Ministry of Education, exam by the state', 'A scholarship for Class 8 students in government, local body and aided schools, paid each year from Class 9 to Class 12 if the student keeps studying. Selection is through a state-level exam.', '{"studyingAt":["class8"],"manualChecks":["Studying in a government, local body or government-aided school (not Navodaya, KV or residential schools)","Family income and Class 7 marks limits in this year''s notice"]}'::jsonb, '{"amount":"Paid yearly for Classes 9 to 12; check the current amount in the notice","selection":"State-level exam (mental ability and scholastic aptitude)","entryClass":"Classes 9 to 12","tags":["school","merit","income"]}'::jsonb, null, 'https://scholarships.gov.in', 'National Scholarship Portal', null, 'in-review', true)
